import React, { useState, useEffect, useCallback } from 'react';
import FrostedContainer from './FrostedContainer';
import Button from './Button';
import './UserPanel.css';

const UserPanel = ({ user, onLogout, onBackToFolders }) => {
  const [files, setFiles] = useState([]);
  const [currentView, setCurrentView] = useState('privada');
  const [currentPath, setCurrentPath] = useState([]);
  const [loading, setLoading] = useState(true);
  const [sidebarExpanded, setSidebarExpanded] = useState(true);
  const [uploadMenuOpen, setUploadMenuOpen] = useState(false);
  const [sharedFolders, setSharedFolders] = useState([]);
  const [storageUsed, setStorageUsed] = useState(0);
  const [storageLimit] = useState(5 * 1024 * 1024 * 1024); // 5GB

  const loadFiles = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/files', {
        headers: {
          'Authorization': `Bearer ${user?.token}`
        }
      });
      const data = await response.json();
      setFiles(data.files || []);
      setStorageUsed(data.storageUsed || 0);
    } catch (error) {
      console.error('Error loading files:', error);
    } finally {
      setLoading(false);
    }
  }, [user?.token]);

  const loadSharedFolders = useCallback(async () => {
    try {
      const response = await fetch('/api/shared-folders', {
        headers: {
          'Authorization': `Bearer ${user?.token}`
        }
      });
      const data = await response.json();
      setSharedFolders(data.folders || []);
    } catch (error) {
      console.error('Error loading shared folders:', error);
    }
  }, [user?.token]);

  useEffect(() => {
    loadFiles();
    loadSharedFolders();
  }, [currentView, currentPath, loadFiles, loadSharedFolders]);

  const handleFileUpload = async (files) => {
    try {
      for (let file of files) {
        const formData = new FormData();
        formData.append('file', file);
        formData.append('path', currentPath.join('/'));

        const response = await fetch('/api/files/upload', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${user?.token}`
          },
          body: formData
        });

        if (!response.ok) {
          throw new Error('Error uploading file');
        }
      }
      loadFiles(); // Reload files after upload
    } catch (error) {
      console.error('Error uploading files:', error);
    }
  };

  const handleFolderUpload = async (files) => {
    try {
      // Handle folder upload (webkitdirectory)
      for (let file of files) {
        const relativePath = file.webkitRelativePath;
        const formData = new FormData();
        formData.append('file', file);
        formData.append('path', currentPath.join('/'));
        formData.append('relativePath', relativePath);

        const response = await fetch('/api/files/upload-folder', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${user?.token}`
          },
          body: formData
        });

        if (!response.ok) {
          throw new Error('Error uploading folder');
        }
      }
      loadFiles(); // Reload files after upload
    } catch (error) {
      console.error('Error uploading folder:', error);
    }
  };

  const changeView = (view) => {
    setCurrentView(view);
    setCurrentPath([]);
  };

  const navigateToFolder = (folderName) => {
    setCurrentPath([...currentPath, folderName]);
  };

  const goBack = () => {
    if (currentPath.length > 0) {
      setCurrentPath(currentPath.slice(0, -1));
    }
  };

  const getCurrentFiles = () => {
    let currentFiles = files;
    for (const folder of currentPath) {
      const folderItem = currentFiles.find(item => item.type === 'folder' && item.name === folder);
      if (folderItem && folderItem.children) {
        currentFiles = folderItem.children;
      } else {
        return [];
      }
    }
    return currentFiles;
  };

  const formatFileSize = (bytes) => {
    if (bytes >= 1024 * 1024 * 1024) return (bytes / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
    if (bytes >= 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
    if (bytes >= 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return bytes + ' B';
  };

  const getStoragePercentage = () => {
    return Math.min(100, (storageUsed / storageLimit) * 100);
  };

  return (
    <div className="user-panel">
      {/* Background */}
      <div className="bg"></div>

      {/* Sidebar */}
      <div className={`sidebar ${sidebarExpanded ? 'expanded' : 'collapsed'}`}>
        <div className="sidebar-content">
          {/* Logo */}
          <div className="logo">
            <img className="logo-img" src="/icons/nube.png" alt="Nube" />
            <span className="logo-text">Nube Personal</span>
          </div>

          {/* Upload Button */}
          <div className="upload-btn-wrapper">
            <Button
              variant="frosted"
              onClick={() => setUploadMenuOpen(!uploadMenuOpen)}
              className="upload-btn"
            >
              <span>⬆️</span> Subir
            </Button>
            {uploadMenuOpen && (
              <FrostedContainer variant="card" className="upload-menu">
                <button className="upload-menu-item" onClick={() => document.getElementById('fileInput').click()}>
                  📄 Subir archivos
                </button>
                <button className="upload-menu-item" onClick={() => document.getElementById('folderInput').click()}>
                  📁 Subir carpeta
                </button>
              </FrostedContainer>
            )}
          </div>

          {/* Navigation */}
          <nav className="sidebar-nav">
            <Button
              variant={currentView === 'privada' ? 'primary' : 'secondary'}
              onClick={() => changeView('privada')}
              className="sidebar-btn"
            >
              <span>🗂️</span> Mi unidad
            </Button>

            {/* Shared Folders Dropdown */}
            <div className="dropdown-container">
              <Button
                variant={currentView.startsWith('shared') ? 'primary' : 'secondary'}
                onClick={() => {/* toggle dropdown */}}
                className="sidebar-btn"
              >
                <span>🌍</span> Compartidos
                <span className="dropdown-arrow">▾</span>
              </Button>
              <div className="dropdown-content">
                <button className="dropdown-item" onClick={() => changeView('public')}>
                  📂 Compartido general
                </button>
                {sharedFolders.map(folder => (
                  <button
                    key={folder.id}
                    className="dropdown-item"
                    onClick={() => changeView(`shared-${folder.id}`)}
                  >
                    👥 Con {folder.withUser}
                  </button>
                ))}
                <button className="dropdown-item" onClick={() => {/* open create shared modal */}}>
                  ➕ Nueva carpeta compartida
                </button>
              </div>
            </div>
          </nav>

          {/* Storage Bar */}
          <div className="storage-info">
            <div className="storage-text">
              {formatFileSize(storageUsed)} de {formatFileSize(storageLimit)}
            </div>
            <div className="storage-bar">
              <div
                className="storage-bar-fill"
                style={{ width: `${getStoragePercentage()}%` }}
              ></div>
            </div>
          </div>

          {/* Actions */}
          <div className="sidebar-actions">
            <Button variant="secondary" onClick={onBackToFolders}>
              ⬅️ Volver
            </Button>
            <Button variant="secondary" onClick={() => window.open('/calendar', '_blank')}>
              📅 Abrir calendario
            </Button>
            <Button variant="secondary" onClick={onLogout}>
              🚪 Cerrar sesión
            </Button>
          </div>
        </div>
      </div>

      {/* Main Panel */}
      <div className="main-panel">
        <div className="panel-header">
          <div className="panel-title">
            {currentView === 'privada' ? 'Mi unidad' :
             currentView === 'public' ? 'Compartido general' :
             currentView.startsWith('shared') ? 'Carpeta compartida' :
             'Archivos'}
          </div>
        </div>

        <div className="file-grid">
          {loading ? (
            <div className="loading">Cargando archivos...</div>
          ) : (
            <>
              {/* Back button */}
              {currentPath.length > 0 && (
                <Button variant="secondary" onClick={goBack} className="back-btn">
                  ⬅ Volver
                </Button>
              )}

              {/* Files and folders */}
              {getCurrentFiles().map((item, index) => (
                <FileItem
                  key={`${item.name}-${index}`}
                  item={item}
                  onFolderClick={navigateToFolder}
                />
              ))}

              {/* Empty state */}
              {getCurrentFiles().length === 0 && !loading && (
                <div className="empty-state">
                  <span>📁</span>
                  <p>No hay archivos en esta carpeta</p>
                </div>
              )}
            </>
          )}
        </div>
      </div>

      {/* Hidden file inputs */}
      <input
        type="file"
        id="fileInput"
        multiple
        style={{ display: 'none' }}
        onChange={(e) => handleFileUpload(e.target.files)}
      />
      <input
        type="file"
        id="folderInput"
        webkitdirectory=""
        style={{ display: 'none' }}
        onChange={(e) => handleFolderUpload(e.target.files)}
      />
    </div>
  );
};

// File Item Component
const FileItem = ({ item, onFolderClick }) => {
  const [menuOpen, setMenuOpen] = useState(false);

  const handleClick = () => {
    if (item.type === 'folder') {
      onFolderClick(item.name);
    } else {
      // Open file
      window.open(`/api/files/${item.id}`, '_blank');
    }
  };

  const handleMenuClick = (e) => {
    e.stopPropagation();
    setMenuOpen(!menuOpen);
  };

  return (
    <FrostedContainer variant="card" className="file-item">
      <div className="file-thumbnail" onClick={handleClick}>
        {item.type === 'folder' ? (
          <span className="file-icon">📁</span>
        ) : (
          <span className="file-icon">📄</span>
        )}
        {item.shared && <span className="shared-badge">🤝</span>}
      </div>

      <div className="file-info">
        <div className="file-name" title={item.name}>
          {item.name}
        </div>
        {item.type === 'file' && (
          <div className="file-size">
            {formatFileSize(item.size)}
          </div>
        )}
      </div>

      <button className="file-menu-btn" onClick={handleMenuClick}>
        ⋮
      </button>

      {menuOpen && (
        <div className="file-menu">
          {item.type === 'file' ? (
            <>
              <button onClick={() => window.open(`/api/files/${item.id}`, '_blank')}>
                👁 Ver
              </button>
              <button onClick={() => window.open(`/api/files/${item.id}?download=true`)}>
                ⬇️ Descargar
              </button>
            </>
          ) : (
            <>
              <button onClick={() => onFolderClick(item.name)}>
                📁 Abrir
              </button>
            </>
          )}
          <button>📋 Duplicar</button>
          <button>📁 Mover</button>
          <button>✏️ Renombrar</button>
          <button className="danger">🗑️ Eliminar</button>
        </div>
      )}
    </FrostedContainer>
  );
};

const formatFileSize = (bytes) => {
  if (!bytes) return '0 B';
  if (bytes >= 1024 * 1024 * 1024) return (bytes / (1024 * 1024 * 1024)).toFixed(2) + ' GB';
  if (bytes >= 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
  if (bytes >= 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return bytes + ' B';
};

export default UserPanel;
